def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        opp = history[0][1]
        return 'D' if opp == 'D' else 'C'
    def run_len_of_last_opponent_action():
        last = history[-1][1]
        k = 0
        for i in range(n - 1, -1, -1):
            if history[i][1] == last:
                k += 1
            else:
                break
        return k
    def run_len_of_last_own_action():
        last = history[-1][0]
        k = 0
        for i in range(n - 1, -1, -1):
            if history[i][0] == last:
                k += 1
            else:
                break
        return k
    def count_opponent(action):
        s = 0
        for h in history:
            if h[1] == action:
                s += 1
        return s
    def last_moves(k):
        start = max(0, n - k)
        out = []
        for i in range(start, n):
            out.append(history[i])
        return out
    my_last = history[-1][0]
    opp_last = history[-1][1]
    my_score = 0
    opp_score = 0
    for h in history:
        a, b = h
        if a == 'C' and b == 'C':
            my_score += 3
            opp_score += 3
        elif a == 'C' and b == 'D':
            my_score += 0
            opp_score += 5
        elif a == 'D' and b == 'C':
            my_score += 5
            opp_score += 0
        else:
            my_score += 1
            opp_score += 1
    rounds_left = 100 - n
    if rounds_left <= 0:
        return 'D'
    d_count = count_opponent('D')
    c_count = n - d_count
    opp_d_ratio = float(d_count) / float(n) if n else 0.0
    opp_last_d_run = run_len_of_last_opponent_action() if opp_last == 'D' else 0
    opp_last_c_run = run_len_of_last_opponent_action() if opp_last == 'C' else 0
    my_last_d_run = run_len_of_last_own_action() if my_last == 'D' else 0
    my_last_c_run = run_len_of_last_own_action() if my_last == 'C' else 0
    if n >= 6:
        tail = last_moves(6)
        tail_opp_d = 0
        tail_opp_c = 0
        tail_my_d = 0
        tail_my_c = 0
        for a, b in tail:
            if a == 'D':
                tail_my_d += 1
            else:
                tail_my_c += 1
            if b == 'D':
                tail_opp_d += 1
            else:
                tail_opp_c += 1
        if tail_opp_d >= 5:
            return 'D'
        if tail_opp_c >= 5 and tail_my_d >= 4:
            return 'C'
    if n >= 3:
        recent = last_moves(3)
        if all(h[1] == 'D' for h in recent):
            return 'D'
        if all(h[1] == 'C' for h in recent) and all(h[0] == 'C' for h in recent):
            return 'C'
    if opp_last == 'D':
        if opp_last_d_run >= 3:
            return 'D'
        if opp_d_ratio > 0.35:
            return 'D'
        if my_last == 'D':
            if rng.random() < 0.55:
                return 'D'
            return 'C'
        return 'D'
    else:
        if opp_last_c_run >= 4:
            if my_last == 'D':
                return 'C'
            return 'C'
        if opp_d_ratio > 0.55:
            if rng.random() < 0.45:
                return 'D'
            return 'C'
        if my_last == 'D':
            return 'C'
        if my_score + 6 < opp_score and rounds_left > 10:
            return 'D'
        return 'C'
